window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b3c25762e9c66786"]={"versions": [{"id": "FIG-b3c25762e9c66786", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine) zur Spezifikation der Statuslogik von DTC-Statusbit 6 (<code>TestNotCompletedThisOperationCycle</code>) gemäß ISO 14229-1 innerhalb des AUTOSAR Diagnostic Event Manager (<code>Dem</code>). Das Diagramm modelliert den Lebenszyklus und die Übergangsbedingungen dieses Statusbits bezogen auf Diagnoseereignisse und Betriebszyklen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Zustände, Schnittstellen und Parameter:</p>\n<ul class=\"fig-list\">\n<li>Zustände:</li>\n<li>Pseudo-Startzustand: <code>Initial state</code> (Initialisierung von Bit 6)</li>\n<li><code>TestNotCompletedThisOperationCycle = TRUE</code></li>\n<li><code>TestNotCompletedThisOperationCycle = FALSE</code></li>\n<li>Schnittstellen und API-Trigger:</li>\n<li><code>Dem_SetOperationCycleState(OperationCycleId, CycleState = DEM_CYCLE_STATE_START)</code></li>\n<li><code>[SWS_Dem_00385] Dem_&lt;...&gt;ClearDTC(DTC, DTCFormat, DTCOrigin)</code></li>\n<li><code>Dem_[SetEvent|ReportError]Status(EventId, EventStatus = DEM_EVENT_STATUS_[FAILED|PASSED])</code></li>\n<li>Bedingungen und Annotationen: Fußnoten/Bedingungsmarker <code>[A]</code> und <code>[B]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Zustandsübergangsablauf gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\">\n<li>Vom <code>Initial state</code> führt ein unbedingter Initialisierungsübergang (<code>Bit 6</code>) direkt in den Zustand <code>TestNotCompletedThisOperationCycle = TRUE</code>.</li>\n<li>Übergang von <code>TRUE</code> nach <code>FALSE</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ausgelöst durch den Funktionsaufruf <code>Dem_[SetEvent|ReportError]Status(EventId, EventStatus = DEM_EVENT_STATUS_[FAILED|PASSED])</code> unter Bedingung <code>[B]</code>. Sobald ein Testergebnis (weder unbestimmt noch ungeprüft, sondern entweder <code>PASSED</code> oder <code>FAILED</code>) vorliegt, wechselt Bit 6 auf <code>FALSE</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Verbleib in Zustand <code>FALSE</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eine Selbsttransition (Loop) an <code>TestNotCompletedThisOperationCycle = FALSE</code> verarbeitet wiederholte Aufrufe von <code>Dem_[SetEvent|ReportError]Status(EventId, EventStatus = DEM_EVENT_STATUS_[FAILED|PASSED])</code>, ohne den Zustand zu ändern.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Rückfall von <code>FALSE</code> nach <code>TRUE</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ausgelöst durch <code>Dem_SetOperationCycleState(OperationCycleId, CycleState = DEM_CYCLE_STATE_START)</code> unter Bedingung <code>[A]</code> (Beginn eines neuen Betriebszyklus) ODER durch Löschen der Diagnose-Informationen via <code>Dem_&lt;...&gt;ClearDTC(DTC, DTCFormat, DTCOrigin)</code> gemäß Anforderung <code>[SWS_Dem_00385]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm besitzt normative Verbindlichkeit für das Dem-Modul hinsichtlich der Handhabung des UDS DTC-Statusbytes (Bit 6):</p>\n<ul class=\"fig-list\">\n<li>Zu Beginn jedes Betriebszyklus (<code>DEM_CYCLE_STATE_START</code>) oder nach dem Löschen von DTCs muss Bit 6 zwingend auf 1 (<code>TRUE</code>) gesetzt werden, um anzuzeigen, dass der Diagnosetest im aktuellen Zyklus noch nicht vollständig durchlaufen wurde.</li>\n<li>Erst wenn ein gültiges Testergebnis (<code>PASSED</code> oder <code>FAILED</code>) über <code>Dem_SetEventStatus</code> bzw. <code>Dem_ReportErrorStatus</code> gemeldet wird, darf Bit 6 auf 0 (<code>FALSE</code>) zurückgesetzt werden.</li>\n<li>Implementierer müssen sicherstellen, dass ClearDTC-Operationen den Zyklusstatus zurücksetzen und Mehrfachmeldungen innerhalb desselben Zyklus den Zustand <code>FALSE</code> nicht verlassen.</li>\n</ul>"}, {"id": "FIG-e3165cdabf6b3766", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine) zur Spezifikation der Statuslogik von DTC-Statusbit 6 (<code>TestNotCompletedThisOperationCycle</code>) gemäß ISO 14229-1 innerhalb des AUTOSAR Diagnostic Event Manager (<code>Dem</code>). Das Diagramm modelliert den Lebenszyklus und die Übergangsbedingungen dieses Statusbits bezogen auf Diagnoseereignisse und Betriebszyklen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Zustände, Schnittstellen und Parameter:</p>\n<ul class=\"fig-list\">\n<li>Zustände:</li>\n<li>Pseudo-Startzustand: <code>Initial state</code> (Initialisierung von Bit 6)</li>\n<li><code>TestNotCompletedThisOperationCycle = TRUE</code></li>\n<li><code>TestNotCompletedThisOperationCycle = FALSE</code></li>\n<li>Schnittstellen und API-Trigger:</li>\n<li><code>Dem_SetOperationCycleState(OperationCycleId, CycleState = DEM_CYCLE_STATE_START)</code></li>\n<li><code>[SWS_Dem_00385] Dem_&lt;...&gt;ClearDTC(DTC, DTCFormat, DTCOrigin)</code></li>\n<li><code>Dem_[SetEvent|ReportError]Status(EventId, EventStatus = DEM_EVENT_STATUS_[FAILED|PASSED])</code></li>\n<li>Bedingungen und Annotationen: Fußnoten/Bedingungsmarker <code>[A]</code> und <code>[B]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Zustandsübergangsablauf gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\">\n<li>Vom <code>Initial state</code> führt ein unbedingter Initialisierungsübergang (<code>Bit 6</code>) direkt in den Zustand <code>TestNotCompletedThisOperationCycle = TRUE</code>.</li>\n<li>Übergang von <code>TRUE</code> nach <code>FALSE</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ausgelöst durch den Funktionsaufruf <code>Dem_[SetEvent|ReportError]Status(EventId, EventStatus = DEM_EVENT_STATUS_[FAILED|PASSED])</code> unter Bedingung <code>[B]</code>. Sobald ein Testergebnis (weder unbestimmt noch ungeprüft, sondern entweder <code>PASSED</code> oder <code>FAILED</code>) vorliegt, wechselt Bit 6 auf <code>FALSE</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Verbleib in Zustand <code>FALSE</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eine Selbsttransition (Loop) an <code>TestNotCompletedThisOperationCycle = FALSE</code> verarbeitet wiederholte Aufrufe von <code>Dem_[SetEvent|ReportError]Status(EventId, EventStatus = DEM_EVENT_STATUS_[FAILED|PASSED])</code>, ohne den Zustand zu ändern.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Rückfall von <code>FALSE</code> nach <code>TRUE</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ausgelöst durch <code>Dem_SetOperationCycleState(OperationCycleId, CycleState = DEM_CYCLE_STATE_START)</code> unter Bedingung <code>[A]</code> (Beginn eines neuen Betriebszyklus) ODER durch Löschen der Diagnose-Informationen via <code>Dem_&lt;...&gt;ClearDTC(DTC, DTCFormat, DTCOrigin)</code> gemäß Anforderung <code>[SWS_Dem_00385]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm besitzt normative Verbindlichkeit für das Dem-Modul hinsichtlich der Handhabung des UDS DTC-Statusbytes (Bit 6):</p>\n<ul class=\"fig-list\">\n<li>Zu Beginn jedes Betriebszyklus (<code>DEM_CYCLE_STATE_START</code>) oder nach dem Löschen von DTCs muss Bit 6 zwingend auf 1 (<code>TRUE</code>) gesetzt werden, um anzuzeigen, dass der Diagnosetest im aktuellen Zyklus noch nicht vollständig durchlaufen wurde.</li>\n<li>Erst wenn ein gültiges Testergebnis (<code>PASSED</code> oder <code>FAILED</code>) über <code>Dem_SetEventStatus</code> bzw. <code>Dem_ReportErrorStatus</code> gemeldet wird, darf Bit 6 auf 0 (<code>FALSE</code>) zurückgesetzt werden.</li>\n<li>Implementierer müssen sicherstellen, dass ClearDTC-Operationen den Zyklusstatus zurücksetzen und Mehrfachmeldungen innerhalb desselben Zyklus den Zustand <code>FALSE</code> nicht verlassen.</li>\n</ul>"}], "trans": [{"from": "FIG-b3c25762e9c66786", "to": "FIG-e3165cdabf6b3766", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
